/* Label things */
body > div {
  display: flow-root;
}
body > div::before {
  display: block;
  content: attr(class);
  font-size: 10px;
  margin-top: 10px;
}

/* Test Framework */
.container {
  border: solid aqua;
  margin: 10px;
  float: right;
  width: 30px;
  height: 30px;
}

.item {
  background: orange;
  height: 100%;
}

/* Test */
.small .item {
  width: 20px;
}
.large .item {
  width: 40px;
}

.small .center
  { margin-right: 5px }
.small .end,
.small .self-end,
.small .flex-end
  { margin-right: 10px }
.large .center
  { margin-right: -5px; }
.large .end,
.large .self-end,
.large .flex-end
  { margin-right: -10px; }
.safe .item
  { margin-right: 0; }
